//
//  ThemeTokens.swift
//  Omarchy Auto — iOS edition
//
//  Decodes design/omarchy-themes.json (schema 1), the deterministic export of
//  the Android repo's Theme.kt palettes (ADR-0017). The file is generated by
//  ./gradlew exportDesignTokens -Pomarchy.updateDesignTokens=true and is
//  byte-stable, so it can be vendored as a bundle resource.
//
//  Status: compiled and unit-tested by CI on GitHub's macos-26 runner
//  (Xcode 26) — no local Mac required for the tokens package; see
//  ThemeTokensTests for the decode assertions. The app and widget targets
//  bundle omarchy-themes.json when the Xcode project lands (beads
//  omarchy-h7w.6 / .3) and consume this package as their decoding contract.
//

import Foundation

/// One Omarchy palette, mirroring the Kotlin `OmarchyTheme` field-for-field.
/// Colors are the JSON `#AARRGGBB` strings; alphas are 0...255.
public struct ThemeToken: Codable, Equatable {
    public let id: String
    public let name: String
    public let shortName: String
    public let background: String
    public let surface: String
    public let surfaceAlt: String
    public let foreground: String
    public let dim: String
    public let border: String
    public let accent: String
    public let green: String
    public let yellow: String
    public let red: String
    public let scrimAlpha: Int
    public let stageAlpha: Int

    /// Every color field, in schema order.
    public var colors: [String] {
        [background, surface, surfaceAlt, foreground, dim, border, accent, green, yellow, red]
    }

    /// Splits a `#AARRGGBB` token into (alpha, red, green, blue), each 0...255.
    public static func components(ofHex hex: String) -> (a: Int, r: Int, g: Int, b: Int)? {
        guard hex.count == 9, hex.first == "#",
              let value = UInt32(hex.dropFirst(), radix: 16)
        else { return nil }
        return (
            Int((value >> 24) & 0xFF),
            Int((value >> 16) & 0xFF),
            Int((value >> 8) & 0xFF),
            Int(value & 0xFF)
        )
    }
}

/// Root object of design/omarchy-themes.json.
public struct ThemeTokenFile: Codable, Equatable {
    public let schema: Int
    public let source: String
    public let colorFormat: String
    public let alphaRange: String
    public let themes: [ThemeToken]
}

public enum ThemeTokenError: Error, Equatable {
    case unsupportedSchema(Int)
    case unexpectedColorFormat(String)
    case invalidColor(String, themeID: String)
    case alphaOutOfRange(Int, themeID: String)
}

public enum ThemeTokens {

    /// Loads and validates design/omarchy-themes.json from a bundle resource
    /// or file URL. Throws `ThemeTokenError` on any schema or value drift.
    public static func load(contentsOf url: URL) throws -> ThemeTokenFile {
        let file = try JSONDecoder().decode(ThemeTokenFile.self, from: Data(contentsOf: url))
        try validate(file)
        return file
    }

    /// Loads design/omarchy-themes.json from a bundle by resource name.
    public static func load(from bundle: Bundle, resource: String = "omarchy-themes") throws -> ThemeTokenFile {
        guard let url = bundle.url(forResource: resource, withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try load(contentsOf: url)
    }

    public static func validate(_ file: ThemeTokenFile) throws {
        guard file.schema == 1 else { throw ThemeTokenError.unsupportedSchema(file.schema) }
        guard file.colorFormat == "#AARRGGBB" else {
            throw ThemeTokenError.unexpectedColorFormat(file.colorFormat)
        }
        for theme in file.themes {
            for hex in theme.colors {
                guard ThemeToken.components(ofHex: hex) != nil else {
                    throw ThemeTokenError.invalidColor(hex, themeID: theme.id)
                }
            }
            guard (0...255).contains(theme.scrimAlpha) else {
                throw ThemeTokenError.alphaOutOfRange(theme.scrimAlpha, themeID: theme.id)
            }
            guard (0...255).contains(theme.stageAlpha) else {
                throw ThemeTokenError.alphaOutOfRange(theme.stageAlpha, themeID: theme.id)
            }
        }
    }
}
